function CompetePointRewardsDialog:RefreshPointList()
    if not self.TaskListView.IsListViewInit then
        self.TaskListView:InitListView(#self.pointRewardsArray, Bind(self, self.OnUpdateTaskListCellHandler_))
    else
        self.TaskListView:MovePanelToItemIndex(0)
    end
end


