-- handler

function CompetePointRewardsDialog:OnClickCloseButtonHandler_()
    UIModule.CloseDialog(self.controller)
end


function CompetePointRewardsDialog:OnUpdateTaskListCellHandler_(listView, listIndex)
    if listIndex < 0 then return end
    local cell = listView:NewListViewItem("Cell")
    ---@type LadderCompetionTaskRewardCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, CompetePointRewardsCellNode)
    if nodeEnv then
        local luaIndex = listIndex + 1
        local cellData = checkTable( self.pointRewardsArray[luaIndex])
        -- init cell
        nodeEnv:SetLuaIndex(luaIndex)
        nodeEnv:SetCellData(cellData)
        nodeEnv:SetClickCB(Bind(self, self.OnClickTaskListCellCallback_))
        -- init anim
        if self.itemShowNum_ == nil then
            local cellSizeH   = cell.CachedRectTransform.rect.height + cell.Padding
            self.itemShowNum_ = math.ceil(self.TaskListView.ViewPortHeight / cellSizeH)
        end
        if not self.cellAnimMap_[luaIndex] and listIndex <= self.itemShowNum_ then
            self.cellAnimMap_[luaIndex] = true
            nodeEnv:PlayAnimByEnter(listIndex)
        else
            nodeEnv:PlayAnimByShowed()
        end
    end
    return cell
end


function CompetePointRewardsDialog:DrawRewards(id)
    local comp = self:GetComponent()
    GameUtils.Request(Interfaces.ActivityUserPkDrawPointReward, { activityUuid = comp:GetActivityUuid(), id = id },
            function(request, response)
                if checkNumber(response.errCode) == 0 then
                    -- draw rewards
                    local rewardList = checkTable(response.data.rewards)
                    GoodsUtils.DrawRewards(rewardList, true)
                    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.UICommonRewardPop, { rewards = rewardList }))
                    local drawIndexs = {}
                    -- id 存在 单个领取
                    if id then
                        id = checkInt(id)
                        for i, v in pairs(self.pointRewardsArray) do
                            if checkInt(v.id ) == id then
                                drawIndexs[tostring(i)] = true
                                comp:SetGrandPointStatusById(v.id, Constants.GetStatus.Has)
                                break
                            end
                        end
                    else
                        local point = checkInt(comp:GetPlayerRank().point)
                        for i, v in pairs(self.pointRewardsArray) do
                            if checkInt(v.needPoint) <= point then
                                drawIndexs[tostring(i)] = true
                                comp:SetGrandPointStatusById(v.id, Constants.GetStatus.Has)
                            end
                        end
                    end
                    for itemCount = 1, self.TaskListView.ShownItemCount do
                        local cellNode = self.TaskListView:GetShownItemByIndex(itemCount - 1)
                        if not isNull(cellNode) then
                            ---@type CompetePointRewardsCellNode
                            local nodeEnv = CfUtils.GetLuaScr(cellNode, CompetePointRewardsCellNode)
                            if nodeEnv then
                                local cellLuaIndex = nodeEnv:GetLuaIndex()
                                if drawIndexs[tostring(cellLuaIndex)] then
                                    nodeEnv:SetCellData(self.pointRewardsArray[cellLuaIndex])
                                    if id then
                                        break
                                    end
                                end
                            end
                        end
                    end
                    -- refresh red point
                    self:RefreshRedPointState_()
                end
            end
    )
end

function CompetePointRewardsDialog:AllDrawRewardsClick()
    local comp = self:GetComponent()
    local isHaveDraw = false
    for i, v in pairs(self.pointRewardsArray) do
        local status = comp:GetGrandPointStatusById(v.id)
        if  status == Constants.GetStatus.Can then
            isHaveDraw = true
            break
        end
    end
    if not isHaveDraw then
        GameUtils.Toast(localize("暂无奖励可领取"))
        return
    end
    self:DrawRewards()
end

function CompetePointRewardsDialog:OnClickTaskListCellCallback_(luaIndex)
    local comp = self:GetComponent()
    local cellData = checkTable(self.pointRewardsArray[luaIndex])
    local statusId = checkInt(comp:GetGrandPointStatusById(cellData.id))
    if statusId == Constants.GetStatus.Not then
        GameUtils.Toast(localize('不能领取'))
        return
    end
    if statusId == Constants.GetStatus.Has then
        GameUtils.Toast(localize('已领取'))
        return
    end
    self:DrawRewards(cellData.id)
end


return CompetePointRewardsDialog
